export function getMinimumScoresForGroup(groupCode: string): MinimumScore[] {
  return minimumScores.filter((m) => m.groupCode === groupCode);
}

export function getMinimumScore(universityId: string, groupCode: string): MinimumScore | undefined {
  return minimumScores.find((m) => m.universityId === universityId && m.groupCode === groupCode);
}